import { recipe } from '../detail-helpers-v1.js';
const gatherings='Neighbors hold a quiet vigil|The congregation shares a simple meal|Visitors join a remembrance service|The temple hosts an evening gathering|Families gather for a reading|The keeper leads a short observance|Neighbors meet for a candlelit service|Visitors gather for a blessing|The temple holds a morning service|The congregation gathers for a song';
const purposes='to remember absent friends.|to welcome new arrivals.|to mark the change of season.|to give thanks for help received.|to remember former residents of {district}.|to support neighbors facing hardship.|to honor those who have died.|to welcome travelers before a journey.|to offer comfort to grieving households.|to celebrate a reunion.';
export const observances=recipe(gatherings,purposes);
const cargo='sacks of grain|sealed storage jars|bundles of wool|timber lengths|empty barrels|bales of canvas|crates of pottery|coils of rope|baskets of dried provisions|bundles of sailcloth';
export const portActivity=recipe('The quay crew is unloading|A carrier is collecting|Porters are weighing|Workers are stacking|The cargo keeper is inspecting|A buyer is checking|A factor is counting|Porters are loading|A clerk is tallying|The receiving crew is sorting',cargo.split('|').map(v=>`${v}.`));
const ordinaryTasks='A shutter needs repair.|Lamp oil needs restocking.|A borrowed pot is ready to return.|A repaired coat needs collecting.|A family letter needs answering.|The rain barrel needs cleaning.|A loose roof tile needs attention.|Fresh sewing thread is needed.|Winter blankets need sorting.|A neighbor’s parcel is ready to deliver.';
const homeDetails='A work basket holds unfinished mending.|A cupboard holds spare blankets.|A table has been cleared for letter writing.|A window box is being replanted.|A rug has been taken up for repairs.|A clay stove has been cleaned.|A chest holds festival decorations.|A basket of apples stands by the pantry.|A stack of slates is ready for lessons.|A shelf holds family keepsakes.';
export const household=recipe(homeDetails,ordinaryTasks);
const schedules={
  shop:'Open from dawn until noon.|Open from noon until dusk.|Open from dawn until dusk.|The counter opens after the morning bell.|The counter opens after noon.|Appointments begin after breakfast.|Visits can be arranged before the evening bell.|Open from late morning until dusk.|Visitors are received in the early afternoon.|The counter closes before supper.',
  temple:'Visitors are welcome from dawn until noon.|Visitors are welcome from noon until dusk.|The temple is open during daylight.|The keeper receives visitors after the morning service.|Quiet visits begin after breakfast.|The doors open at dawn.|Visitors are welcome in the late morning.|The keeper receives callers after noon.|The temple closes before the evening bell.|Afternoon visits end at dusk.',
  guild:'The hall opens after the morning bell.|The steward receives callers before noon.|The hall is open from noon until dusk.|Applications are heard after breakfast.|The hall is open during daylight.|Visitors can call in the late morning.|The public desk opens at noon.|The steward receives callers in the early afternoon.|The hall closes before supper.|The last appointments end at dusk.',
  harbor:'The harbor office opens at dawn.|The keeper receives callers before noon.|The public desk is open from noon until dusk.|Cargo enquiries begin after the morning bell.|Passage enquiries are heard after breakfast.|The office is open during daylight.|The keeper receives visitors in the late morning.|The cargo desk opens after noon.|The office closes before supper.|The final office appointments end at dusk.'
};
const policies={
  shop:'Messages can be left with the keeper.|Groups should arrange a visit first.|Customers can ask for an appointment.|Changes to the hours are posted at the entrance.|Collection times are agreed when ordering.|Visitors can ask for the current price list.|Questions can be sent ahead of a visit.|Appointments can be rearranged with the keeper.|Busy market-day visits are best arranged in advance.|Special requests can be discussed before ordering.',
  temple:'Quiet is requested during services.|Groups should arrange a visit with the keeper.|Visitors can ask about the next observance.|Private conversations can be arranged.|Flowers may be left with the keeper.|The keeper can explain local customs.|Questions about memorials go to the keeper.|Messages for absent families can be left here.|Visitors should ask before interrupting an observance.|Changes to visiting hours are posted at the entrance.',
  guild:'Visitors should ask for the duty steward.|Applicants can ask which documents to bring.|Contract enquiries go to the public desk.|Groups should arrange a meeting first.|The steward can explain membership requirements.|Visitors can ask about the next meeting.|Messages for members can be left at the hall.|Questions can be sent ahead of an appointment.|The duty steward can explain current contracts.|Changes to public hours are posted at the entrance.',
  harbor:'Sailing times are arranged separately.|Crew members can leave messages with the keeper.|Cargo collections are arranged with the carrier.|The keeper can explain the public landing rules.|Visitors should keep loading areas clear.|Passage enquiries go to the public desk.|Office hours do not set boat departure times.|Questions about storage go to the cargo keeper.|The keeper can explain collection arrangements.|Changes to office hours are posted at the entrance.'
};
export const hoursSources=Object.fromEntries(Object.entries(schedules).map(([kind,values])=>[kind,recipe(values,policies[kind])]));
export function civicSources(context) {
  const kind=Object.hasOwn(hoursSources,context.category)?context.category:'shop';
  return {observances,portActivity,household,openingHours:hoursSources[kind]};
}
